# ---------------------------------------------------------------- 工具函数

def iter_page_files():
    """遍历 wiki 下所有正式页面文件（相对 vault 的路径）。"""
    for d in PAGE_DIRS:
        full = os.path.join(WIKI, d)
        if not os.path.isdir(full):
            continue
        for fn in sorted(os.listdir(full)):
            if fn.endswith(".md"):
                yield os.path.join(full, fn)


def is_excluded(path):
    p = path.replace("\\", "/")
    return any(m in p for m in EXCLUDE_DIR_MARKERS)


def read_text(path):
    """以二进制读取后按 UTF-8 解码，并把 CRLF/CR 统一成 LF。

    必须统一换行符：本库文件是 CRLF，而工具链在 Windows 下用文本模式读取时
    换行归一化并不一致，导致 frontmatter 正则失配、元数据静默丢失。
    """
    with open(path, "rb") as f:
        raw = f.read()
    text = raw.decode("utf-8", errors="ignore")
    return text.replace("\r\n", "\n").replace("\r", "\n")


# ---------------------------------------------------------------- frontmatter

_FM_RE = re.compile(r"^---\s*\n(.*?)\n---\s*(?:\n|$)", re.S)


def split_frontmatter(text):
    """返回 (frontmatter_raw, body)。无 frontmatter 时返回 ('', text)。"""
    m = _FM_RE.match(text)
    if not m:
        return "", text
    return m.group(1), text[m.end():]


def _unquote(s):
    s = s.strip()
    if len(s) >= 2 and s[0] == s[-1] and s[0] in ("'", '"'):
        return s[1:-1]
    return s


def parse_frontmatter(raw):
    """
    轻量 YAML 解析：仅支持本库用到的子集
      key: value
      key:
        - item
        - "item"
      key: [a, b]     （行内数组）
    返回 dict，值可能是 str 或 list[str]。
    """
    data = {}
    if not raw:
        return data
    cur_key = None
    for line in raw.split("\n"):
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        # 列表项
        m_item = re.match(r"^\s+-\s+(.*)$", line)
        if m_item and cur_key:
            if not isinstance(data.get(cur_key), list):
                data[cur_key] = []
            data[cur_key].append(_unquote(m_item.group(1)))
            continue
        # 键值对
        m_kv = re.match(r"^([A-Za-z_][\w\-]*)\s*:\s*(.*)$", line)
        if m_kv:
            key, val = m_kv.group(1), m_kv.group(2).strip()
            cur_key = key
            if val == "":
                data[key] = []          # 可能是块状列表
            elif val.startswith("[") and val.endswith("]"):
                inner = val[1:-1].strip()
                data[key] = [_unquote(x) for x in inner.split(",")] if inner else []
            else:
                data[key] = _unquote(val)
            continue
    # 清理：值为空列表且原本应是标量的情况
    return data


# ---------------------------------------------------------------- 分块

def strip_markdown(body, keep_cjk=True):
    """去掉代码块/嵌入/纯 URL，保留可检索文本。"""
    body = re.sub(r"```.*?```", " ", body, flags=re.S)
    body = re.sub(r"!\[\[.*?\]\]", " ", body)          # 嵌入图片
    body = re.sub(r"!\[.*?\]\(.*?\)", " ", body)       # 外链图片
    body = re.sub(r"^\s*\|.*\|\s*$", " ", body, flags=re.M)  # 表格行
    body = re.sub(r"https?://\S+", " ", body)
    body = re.sub(r"\[\s*\]", " ", body)
    body = re.sub(r"[#>*_`~\-]+", " ", body)
    return body


def extract_headings(body):
    return re.findall(r"^#{2,4}\s+(.+)$", body, flags=re.M)


def strip_code(body):
    """剔除围栏代码块与行内代码，只留下"真实正文"。

    🔴 这是本库**代价最高的一类误判**的公共对策：代码块/行内代码里的 `[[...]]`、
    `!![[...]]`、`raw/...` 是**示例文本**（lint 报告和 QC 报告里专门演示"坏写法长什么样"），
    不是真实链接。历史上因为没剔除，出现过：
      · `kb_lint` 报「34 处图片语法错误」（真值 0），改写会破坏排版；
      · `kb_lint_deep` 把 lint 报告里的 `❌[[…]]` 示例当真链接；
      · `kb_restructure` 的 `_RAW_LINK_RE` 会把示例里的 `raw/...` 一起改写。
    实现此前被复制了 3 份并**漏掉了第 4 处**，故收敛到这里唯一一份。
    `qc_fix_image_syntax.code_mask` 仍是需要**位置**时（要按位置改写）的正解；
    只要"剔除后的文本"时用本函数。
    """
    body = re.sub(r"```.*?```", "", body or "", flags=re.S)
    body = re.sub(r"~~~.*?~~~", "", body, flags=re.S)
    return re.sub(r"`[^`\n]*`", "", body)


def extract_outlinks(body):
    """正文中出现的 wikilink 目标（去重、去别名部分）。

    需要同时处理两种免分隔写法：
      [[目标|别名]]      —— 标准形式
      [[目标\\|别名]]    —— Markdown 表格单元格内的转义形式（Obsidian 常用）
    后者在表格里很常见，若只认前者会漏掉大量链接。

    2026-09-22 增补：**剔除围栏代码块与行内代码**——其中的 [[...]] 是示例文本
    （如 lint 报告里演示「坏写法长什么样」），不是真实链接。此前未剔除，
    导致示例写法被误判为失效链接。
    """
    body = strip_code(body)
    out = []
    for m in re.finditer(r"\[\[([^\]\|#\\]+?)(?:\\?[#\|][^\]]*)?\]\]", body):
        t = m.group(1).strip()
        if t and t not in out:
            out.append(t)
    return out


def build_fields(pagename, fm, body):
    """把页面拆成带权重的可检索字段。"""
    aliases = fm.get("aliases") or []
    tags = fm.get("tags") or []
    if isinstance(aliases, str):
        aliases = [aliases]
    if isinstance(tags, str):
        tags = [tags]

    return {
        "title": pagename,
        "aliases": " ".join(aliases),
        "summary": fm.get("summary", "") or "",
        "tags": " ".join(tags),
        "headings": " ".join(extract_headings(body)),
        "body": strip_markdown(body),
    }


# ---------------------------------------------------------------- 分词

_JIEBA = None
_TOKEN_RE = re.compile(r"[A-Za-z][A-Za-z0-9\-\.\+]*|\d+(?:\.\d+)?|[一-鿿]+")


def _get_jieba():
    global _JIEBA
    if _JIEBA is None:
        import jieba
        jieba.setLogLevel(60)      # 静音
        _JIEBA = jieba
    return _JIEBA


def tokenize(text):
    """
    中英混合分词：
      · 连续 CJK 段交给 jieba 切词
      · 英文/数字段整体保留（再拆出纯字母子串以兼顾 "LiFePO4"→"LiFePO4","Li","Fe","PO"）
    统一小写，去停用词与单字符噪声。
    """
    if not text:
        return []
    jb = _get_jieba()
    tokens = []
    for seg in _TOKEN_RE.findall(text):
        if seg[0].isascii():
            t = seg.lower()
            tokens.append(t)
            # 化学式/缩写再拆：LiFePO4 -> li, fe, po4
            parts = re.findall(r"[A-Za-z]+|\d+", seg)
            if len(parts) > 1:
                tokens.extend(p.lower() for p in parts)
        else:
            tokens.extend(jb.lcut(seg))
    out = []
    for t in tokens:
        t = t.strip().lower()
        if not t or t in STOPWORDS or len(t) < 2:
            continue
        if re.fullmatch(r"[\W_]+", t):
            continue
        out.append(t)
    return out


def weighted_tokens(fields):
    """按字段权重加权返回 token 列表（重复即权重）。"""
    tokens = []
    for field, weight in FIELD_WEIGHTS.items():
        txt = fields.get(field, "")
        if not txt:
            continue
        tk = tokenize(txt)
        reps = max(1, int(round(weight)))
        tokens.extend(tk * reps)
    return tokens


# ---------------------------------------------------------------- 别名映射

ACRONYM_RE = re.compile(r"\b[A-Z][A-Za-z]*\b")

# 化学元素/常见单位等「单义性太差」的碎片，不单独作为检索入口
AMBIGUOUS_FRAGMENTS = {
    "li", "na", "k", "zn", "mg", "ca", "al", "fe", "cu", "ni", "co", "mn", "ti", "v",
    "o", "h", "n", "c", "s", "p", "f", "cl", "br", "i", "si", "sn", "ge", "ga", "in",
    "ml", "ai", "dl", "nn", "gp", "bo", "md", "cg", "sd", "us", "id", "in", "on", "by",
}


def derive_alias_forms(name, aliases):
    """
    从页面名与别名派生额外检索入口：
      · 页面名本身的多个「切分形态」（LiFePO4掺杂改性 → LiFePO4、掺杂改性）
      · 从 chinese 别名里抽出的英文缩写（"介质增强电解液 MEE" → MEE）
      · 从英文别名里抽出的首字母缩写（"solid-state electrolyte" → sse 需人工，这里只做显式大写词）
    返回额外别名列表（不含原名）。
    """
    extra = []
    for src in [name] + list(aliases):
        src = str(src).strip()
        if not src:
            continue
        # 1) 混合串切分：连续 ASCII 段 与 连续 CJK 段
        for seg in re.findall(r"[A-Za-z][A-Za-z0-9\-\.\+]*|[一-鿿]+", src):
            if seg != src and len(seg) >= 2:
                extra.append(seg)
        # 2) 显式大写缩写（>=2 位，含数字不算纯缩写）
        for m in ACRONYM_RE.findall(src):
            if len(m) >= 2 and m != src:
                extra.append(m)
    # 去重、去空、去掉等于页面名的
    seen = set()
    out = []
    for e in extra:
        e = e.strip()
        low = e.lower()
        # 丢弃歧义碎片（元素符号/短通用词），显式别名不受此限制
        if low in AMBIGUOUS_FRAGMENTS:
            continue
        if not e or low == name.lower() or low in seen:
            continue
        seen.add(low)
        out.append(e)
    return out


def build_alias_map(pages):
    """
    别名 → 规范页面名。
    pages: {页面名: {aliases:[...], type:...}}
    同别名冲突时，优先保留 concept/entity（比 source 更通用），
    因为概念/实体页是检索时更该命中的「枢纽」。

    分三轮，优先级从高到低：
      ① 页面名 → 自身（最高：一个页面名必须解析到它自己，即使别的页面把它当别名）
      ② 显式别名（按类型优先级：concept > entity > topic > output > source）
      ③ 派生缩写（仅 concept/entity/topic，避免 source 长标题碎片污染通用词）

    第①轮必须先跑：否则某个 source 页把 "柏拉图表征" 写成自己的别名，
    会让该查询解析到文献页而非概念页。
    """
    priority = {"concept": 0, "entity": 1, "topic": 2, "output": 3, "source": 9}
    ordered = sorted(pages.items(),
                     key=lambda kv: priority.get(kv[1].get("type", "source"), 5))

    alias_map = {}

    def put(key, canon, allow_self=False):
        key = key.strip().lower()
        if len(key) < 2:
            return
        if key == canon.lower() and not allow_self:
            return
        if key in alias_map:          # 已被更高优先级轮次占用
            return
        alias_map[key] = canon

    # ① 页面名 → 自身（最高优先级，不可被别名抢占）
    for name in pages:
        put(name, name, allow_self=True)

    # ② 显式别名
    for name, meta in ordered:
        for a in meta.get("aliases", []):
            if a and str(a).strip():
                put(str(a), name)

    # ③ 派生缩写
    DERIVE_TYPES = {"concept", "entity", "topic"}
    for name, meta in ordered:
        if meta.get("type", "source") not in DERIVE_TYPES:
            continue
        aliases = [a for a in (meta.get("aliases") or []) if a]
        for extra in derive_alias_forms(name, aliases):
            put(extra, name)

    return alias_map


def content_hash(fields):
    h = hashlib.md5()
    for k in ("title", "summary", "tags", "aliases", "headings", "body"):
        h.update(fields.get(k, "").encode("utf-8", "ignore"))
    return h.hexdigest()


# ---------------------------------------------------------------- 候选词

def top_terms(fields, n=MAX_CANDIDATE_TERMS):
    """页面最具代表性的词：以 title/aliases/tags/headings 为主。"""
    seen, out = set(), []
    for field in ("title", "aliases", "tags", "headings"):
        for t in tokenize(fields.get(field, "")):
            if t not in seen:
                seen.add(t)
                out.append(t)
            if len(out) >= n:
                return out
    return out


def group_by_type(meta_pages):
    """
    按 type 分组，来源页（sources）用紧凑数组表达以压缩体积：
      pages:       {name: [type, summary, updated, tags, aliases, terms]}
      source_idx:  sources 的列定义 + 行数据
    非来源页面字段少、数量少，保持字典形式（可读）。
    """
    pages = {}
    src_rows = []
    for name, m in sorted(meta_pages.items()):
        if m.get("type") == "source":
            # [name, updated, summary, tags, aliases]
            src_rows.append([
                name,
                m.get("updated", ""),
                m.get("summary", ""),
                m.get("tags", []),
                m.get("aliases", []),
            ])
        else:
            pages[name] = [
                m.get("type", ""),
                m.get("summary", ""),
                m.get("updated", ""),
                m.get("tags", []),
                m.get("aliases", []),
                m.get("terms", []),
            ]
    return pages, src_rows


PAGE_COLS = ["type", "summary", "updated", "tags", "aliases", "terms"]
SOURCE_COLS = ["name", "updated", "summary", "tags", "aliases"]


# ---------------------------------------------------------------- 倒排索引

def to_tf(tokens):
    """加权词序列 → {term: tf}。

    为什么要转 tf 字典：BM25 只需要「某词在某文档出现几次」，
    保留完整重复词序列（加权后平均每页 1900 个 token）纯属浪费——
    它是旧索引 10.4 MB 的主因，也是打分要 `list.count()` 全表线性扫描的根源。
    """
    d = {}
    for t in tokens:
        d[t] = d.get(t, 0) + 1
    return d


def build_postings(doc_tf, doc_names):
    """{页面名: {term: tf}} → (postings, df)

    postings: {term: [[doc_idx, tf], ...]}   —— 真正的**倒排**索引
    df:       {term: 含该词的文档数}

    有了它，BM25 打分只需遍历「查询词对应的 posting 列表」，
    而不是对每个文档做 `list.count()`：复杂度从 O(N·L) 降到 O(命中数)。
    这也是把 raw 全文（536 篇 / 42.5 MB）纳入检索层的前提。
    """
    idx = {n: i for i, n in enumerate(doc_names)}
    postings = {}
    for n in doc_names:
        i = idx[n]
        for t, c in (doc_tf.get(n) or {}).items():
            postings.setdefault(t, []).append([i, c])
    df = {t: len(v) for t, v in postings.items()}
    return postings, df


def tf_from_postings(postings, doc_names):
    """从倒排索引反推 {页面名: {term: tf}}（供增量构建复用未变页面）。"""
    out = {}
    for t, plist in postings.items():
        for di, tf in plist:
            if di < len(doc_names):
                out.setdefault(doc_names[di], {})[t] = tf
    return out


# ---------------------------------------------------------------- DOI 归一
#
# 2026-10-09：实测本库 `local_lit_catalogue.json` 有 15 条 DOI 尾部粘连了中文标点/文字
# （`10.1021/acsnano.5c20611）`、`10.1021/acsenergylett.6c00020，仅用于学术交流）*`），
# 根因是各处 DOI 正则只用 ASCII 标点做边界，而正文里 DOI 后面常紧跟全角括号/顿号。
# 后果是**去重键永远匹配不上 OpenAlex 的干净 DOI ⇒ 那些论文会被重复下载、重复建卡**，
# 且 `source_url` 会生成打不开的 doi.org 链接（尾随句点同样致命）。
#
# 现在把归一化收敛到本函数，全库统一：
#   ① 去 URL 前缀 ② 截断到第一个 CJK/空白/全角字符 ③ 去尾标点 ④ 小写
_DOI_RE = re.compile(r"10\.\d{4,9}/[^\s()\[\]{}<>;,\"']+", re.IGNORECASE)
_DOI_CUT_RE = re.compile(r"[\s\u3000-\u303f\u4e00-\u9fff\uff01-\uff5e\u2000-\u206f]")
_DOI_TAIL = ".,;:)]}>\"'*…、。，；：）】》"


def norm_doi(raw, strip_url=True):
    """把任意来源的 DOI 归一为可比较的规范形式；不是 DOI 就返回空串。"""
    if not raw:
        return ""
    s = str(raw).strip()
    if strip_url:
        s = re.sub(r"^(?:https?://(?:dx\.)?doi\.org/|doi:\s*)", "", s, flags=re.IGNORECASE)
    m = _DOI_RE.search(s)
    if not m:
        return ""                      # 不是 DOI 就明确返回空串，别把任意字符串"归一"成垃圾
    s = m.group(0)
    s = _DOI_CUT_RE.split(s)[0]
    return s.strip().rstrip(_DOI_TAIL).lower()


def doi_looks_complete(doi):
    """完整 DOI 判定：注册号片段（如 `10.1002/anie`、`10.1021/acs`）后缀无数字，不算。"""
    d = norm_doi(doi)
    if not d or "/" not in d:
        return False
    tail = d.split("/", 1)[1]
    return bool(re.search(r"\d", tail)) and bool(re.search(r"[a-z0-9]", tail))


# ---------------------------------------------------------------- lit 配置

LIT_CONFIG_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                               "lit_config.yaml")

# 兜底默认值：即使 yaml 缺失也要能跑，且**全部相对库根**（绝不写绝对路径）
LIT_CONFIG_DEFAULTS = {
    "journals": [],
    "paths": {
        "raw_dir": "raw", "text_dir": "raw/text", "pdf_dir": "raw/pdf",
        "assets_dir": "raw/assets", "notes_dir": "raw/notes",
        # 🆕 2026-10-10：运行产物**离开 _archive/**，落 raw/notes/lit-watch/（见 lit_config.yaml §2）
        "runs_dir": "raw/notes/lit-watch",
        "source_cache": "raw/notes/lit-watch/runs/source_cache.json",
        "download_dir": "raw/notes/lit-watch/downloads",
        "catalogue": "raw/notes/lit-watch/state/local_lit_catalogue.json",
        "extract_ledger": "raw/notes/lit-watch/state/extract_ledger.json",
        "manual_import_log": "raw/notes/lit-watch/state/manual_import_log.json",
        "doi_index": "wiki/.index/dois.json",
    },
    "defaults": {"lookback_days": 7, "max_candidates": 20,
                 "abstract_min_relevance": 0.6, "institution_proxy": True},
    "datasource": {"api": "https://api.openalex.org", "mailto": ""},
    "layout": {"source_page_backlink_prefix": "raw/text",
               "source_page_dir": "wiki/sources"},
}

# 已知顶层段：不在其中的**新段**会被 load_lit_config 原样合并（见下方 ⚠️）
_KNOWN_SECTIONS = ("defaults", "datasource", "layout")


def lit_runs_dir(cfg, *sub):
    """运行产物目录（绝对路径）。子目录约定：`daily` / `picks` / `runs` / `downloads` / `state`。

    🔴 为什么要有这个函数：2026-10-10 之前，`_archive/lit-runs` 在 **6 个文件里被硬编码**
    （lit_daily / lit_digest / lit_doctor / lit_daily_task.ps1 …），只有 lit_fetch 老实读配置 ⇒
    同一个流水线有两个产物根。改路径必须改 6 处，漏一处就静默分叉。
    现在一律经这里派生；新增子目录只改这一处。
    """
    base = (cfg.get("paths") or {}).get("runs_dir") or LIT_CONFIG_DEFAULTS["paths"]["runs_dir"]
    return os.path.join(base, *sub) if sub else base


def load_lit_config(path=None):
    """读取 tools/lit_config.yaml。

    返回的 dict 里：
      cfg["paths"]        路径**已解析为绝对路径**（基于库根，由本文件的 __file__ 推导）
      cfg["paths_rel"]    同一批路径的**相对库根**形式（写进 md 回链时用这种）

    🔴 为什么必须这样：原配置（一份已废弃的旧版配置）把
    8 条 KB 绝对路径写死，Phase 2 重构后其中多条已不存在；而 lit_extract 的默认值
    更指向一个**根本不存在的旧库**（一个已不存在的旧库路径）。
    路径一律由 __file__ 推导 + 配置只写相对形式，改名与重构都不必再改。
    """
    import copy
    cfg = copy.deepcopy(LIT_CONFIG_DEFAULTS)
    p = path or LIT_CONFIG_PATH
    raw_cfg = {}
    if os.path.exists(p):
        try:
            import yaml
            with open(p, encoding="utf-8") as f:
                raw_cfg = yaml.safe_load(f) or {}
            if not isinstance(raw_cfg, dict):
                raise ValueError(f"顶层应为映射，实为 {type(raw_cfg).__name__}")
        except Exception as e:                    # noqa: BLE001
            # 🔴 文件**存在但解析失败**必须 fail fast，不再"改用内置默认值"：
            #    默认值里 journals 为空 ⇒ 白名单失效 ⇒ lit_discover 退化为**全网关键词检索**
            #    （还会把非白名单刊、甚至非材料论文拉进来）。宁可不跑，也不能拿空白名单去检索。
            #    （文件**不存在**是另一回事：仍可回退默认值，见下方 if 之外的分支。）
            raise RuntimeError(f"lit_config.yaml 解析失败（{p}）：{e}") from e
    for section in _KNOWN_SECTIONS:
        for k, v in (raw_cfg.get(section) or {}).items():
            cfg[section][k] = v
    for k, v in (raw_cfg.get("paths") or {}).items():
        cfg["paths"][k] = v
    cfg["journals"] = raw_cfg.get("journals") or []
    # 🆕 2026-10-06：期刊分级（tiers 段 + default_tier）必须**原样透传**，
    #    否则 tier_spec() 取不到阈值/精读档，退化为全局默认（分级静默失效）。
    cfg["tiers"] = raw_cfg.get("tiers") or {}
    cfg["default_tier"] = raw_cfg.get("default_tier") or "T3"
    # 🆕 去重源清单（本机文献目录）与 Zotero 数据目录，同样必须透传。
    cfg["dedup_sources"] = raw_cfg.get("dedup_sources") or []
    cfg["zotero"] = raw_cfg.get("zotero") or {}
    # 🆕 2026-10-10：automation 段（每日发现的方向/窗口/输出目录）也**必须透传**——
    #    与历史 tiers 静默失效同型：不透传时 lit_daily 读不到 directions，
    #    会静默退回内置默认方向，用户改了配置却看不出为什么没生效。
    cfg["automation"] = raw_cfg.get("automation") or {}

    # 🔴 2026-10-10：把上面这条**白名单式透传**改成兜底合并。
    #    历史教训（同一失效形态发生过两次）：`tiers` 与 `automation` 都曾因为在
    #    这个白名单里缺席而被静默丢弃 —— 用户改了配置却看不出为什么没生效。
    #    白名单修一次只管一段；下面这条对所有**未知顶层段**兜底，
    #    并由 kb_selftest 断言「YAML 的每个顶层键都出现在返回的 cfg 里」。
    for k, v in raw_cfg.items():
        if k in cfg:
            continue                      # 已在上面逐段合并过（含 paths 的逐键合并）
        cfg[k] = copy.deepcopy(v)

    # 解析相对路径 → 绝对路径
    cfg["paths_rel"] = dict(cfg["paths"])
    resolved = {}
    for k, v in cfg["paths"].items():
        v = str(v).replace("\\", "/")
        resolved[k] = v if os.path.isabs(v) else os.path.join(VAULT, *v.split("/"))
    cfg["paths"] = resolved
    cfg["_config_path"] = p
    cfg["_vault"] = VAULT
    return cfg


def lit_path(cfg, key):
    """取 lit 配置里的绝对路径，顺带确保父目录存在（可选）。"""
    return cfg["paths"][key]


# ---------------------------------------------------------------- si_status 合法取值（共享）
#
# CLAUDE.md 只定义了 3 个（missing/partial/present），但本库**实况**多一个
# `not_applicable`（"不适用本件"的正当标注）。
#
# 🔴 2026-10-10 实测（全库 724 页）：missing 285 ｜ not_applicable 186 ｜ partial 14 ｜ present 9。
#    另：`kb_lint_deep` 的白名单里还有 `n/a`，注释称"本库实测另有"——**实测为 0 处**，
#    那句注释是假的。故本集合**只收有实测支撑的 4 个值**，不放宽到没有证据的变体。
#
# 为什么收敛到 kb_lib：同一份白名单此前在 `kb_lint.py`（4 值）与 `kb_lint_deep.py`（5 值）
# 各有一份 ⇒ 同一页在两个校验器里可能一个合法一个非法。
# 这正是 CLAUDE.md §校验器自检纪律 第 6 条的形态：**校验器硬编码的"合法值清单"是在断言规范，
# 而不是实况** —— 能自校准的就该自校准。
SI_STATUS_VALUES = frozenset({"missing", "partial", "present", "not_applicable"})
# 供错误信息直接引用，避免两处各写一份说明又各自漂移
SI_STATUS_HINT = "missing/partial/present/not_applicable"


def si_status_ok(v):
    """`si_status` 取值是否合法（去引号后比对）。"""
    return str(v).strip().strip("\"'") in SI_STATUS_VALUES


# ---------------------------------------------------------------- 写盘三件套（共享）
#
# CLAUDE.md §写盘脚本的额外铁律要求三件事：**默认干跑 / 写前同解析器复核 / 写前备份 +
# 写后复算**。此前每个写盘工具各写一份，实现与严格程度都不同：
#   · `kb_lint --deep --fix --apply` 的 docstring 声称"写后复算总量"，**代码里没有**；
#     备份还把文件拍平成 basename ⇒ 不同目录的同名页会互相覆盖备份。
#   · `lit_finish` 有一份很完整的 `write_text_keep_eol`（含混合换行诚实边界说明）与备份。
#   · 5 个 `qc_*` 修复工具**完全没有备份**。
# ⇒ 统一到这里，所有写盘工具共用。

def backup_root(root=None, create=True):
    """备份根目录 `<root>/.qc_backup_YYYYMMDD/`（`root` 默认库根）。

    位置取**库根**而不是 `.qc/` 里面：CLAUDE.md §写盘脚本的额外铁律与 `.gitignore`
    都写作 `.qc_backup_YYYYMMDD/`，`kb_lint` 与 5 个 `qc_*` 修复工具也一直在库根。
    （`lit_finish` 原先把备份放进 `.qc/` 里面——那是同一约定下的分叉，已随本次
    收敛统一到库根；遗留的旧备份仍留在原处，不迁移、不删除。）
    `root` 参数是为**自检隔离**：那些工具的 selftest 把自己的 `ROOT` 指向合成目录，
    备份必须跟着进合成目录，否则"自检不碰真库"的保证就破了。
    """
    return os.path.join(root or VAULT,
                        ".qc_backup_" + datetime.datetime.now().strftime("%Y%m%d"))


def backup_file(path, keep_rel=True, root=None):
    """把文件备份到 `.qc_backup_YYYYMMDD/`，返回备份路径（失败返回 ""）。

    🔴 `keep_rel=True`（默认）**保留相对 `root` 的目录结构**。
    此前 `lit_finish.backup_first` 用 `os.path.basename(path)` 拍平：
    本库 `wiki/{sources,concepts,entities,topics,outputs}/` 之间**存在同名页面**
    ⇒ 后备份的会把先备份的**覆盖掉**，而报告仍说"已备份"。
    备份的价值全在"还原得回来"，同名相撞等于没有备份。
    """
    if not os.path.exists(path):
        return ""
    base = root or VAULT
    try:
        bdir = backup_root(root=base, create=True)
        if keep_rel:
            try:
                rel = os.path.relpath(path, base)
            except ValueError:                                 # 跨盘
                rel = os.path.basename(path)
            if rel.startswith(".."):
                rel = os.path.basename(path)
            dst = os.path.join(bdir, *rel.split(os.sep))
        else:
            dst = os.path.join(bdir, os.path.basename(path))
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        with open(path, "rb") as f:
            data = f.read()
        with open(dst, "wb") as f:
            f.write(data)
        return dst
    except OSError as e:
        print(f"[warn] 备份 {path} 失败：{e}", file=sys.stderr)
        return ""


def detect_eol(path):
    """-> (eol, mixed)：按多数票判定该文件的换行风格。"""
    eol, mixed = "\n", False
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except OSError:
        return eol, mixed
    crlf = raw.count(b"\r\n")
    bare = raw.count(b"\n") - crlf
    if crlf and bare:
        mixed = True
    return ("\r\n" if crlf > bare else "\n"), mixed


def write_text_keep_eol(path, text, quiet=False):
    """原子写文本并**保留原文件的换行风格**（多数票；混合文件会被点名）。返回实际用的 eol。

    为什么必须这样：本库 md 换行是**混合**的，而 `read_text` 归一成 LF；
    直接写回会把 CRLF 文件整份翻转 ⇒ `git diff` 几千行噪声淹没真实改动
    （实测 log_ops.md 曾出现 7132 行 diff，实际只加了 1 行）。

    ⚠️ 诚实边界：混合换行文件**不可能**零 diff。此处不假装修好，而是按多数票写 +
    把混合情况报出来（此前是静默翻转）。
    """
    eol, mixed = detect_eol(path)
    if mixed and not quiet:
        name = "CRLF" if eol == "\r\n" else "LF"
        try:
            shown = os.path.relpath(path, VAULT)
        except ValueError:
            shown = path
        print(f"[!] {shown} 是混合换行文件，按多数票统一为 {name}；"
              f"diff 里会出现该文件的整篇换行噪声（无法避免，换行本就不一致）")
    data = text.replace("\r\n", "\n").replace("\n", eol)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="") as f:
        f.write(data)
    os.replace(tmp, path)          # 原子：中途被杀不会留下半截文件
    return eol


def write_text_verified(path, text, quiet=False, require_frontmatter=None):
    """`write_text_keep_eol` + **写后复算**。-> (ok, detail)。

    复算内容（铁律 3「写 N 页要能读出 N 页」）：
      1. 能重新读出该文件，且**内容与预期逐字节相等**（按归一化换行后比较）；
      2. 若 `require_frontmatter` 为真（或原文件本来就有 frontmatter），
         重读后 `split_frontmatter` 必须仍解析出**非空** frontmatter。
    失败则**不吞**：返回 ok=False 与原因，由调用方决定是否中止。
    """
    if require_frontmatter is None:
        try:
            with open(path, encoding="utf-8", errors="replace",
                      newline="") as f:
                require_frontmatter = bool(split_frontmatter(f.read())[0].strip())
        except OSError:
            require_frontmatter = False
    eol = write_text_keep_eol(path, text, quiet=quiet)
    try:
        with open(path, encoding="utf-8", errors="replace", newline="") as f:
            back = f.read()
    except OSError as e:
        return False, f"写后无法读回：{e}"
    if back.replace("\r\n", "\n") != text.replace("\r\n", "\n"):
        return False, "写后复算不一致（回读内容与写入内容不同）"
    if require_frontmatter and not split_frontmatter(back)[0].strip():
        return False, "写后 frontmatter 解析为空（铁律 2 失败）"
    return True, f"ok(eol={'CRLF' if eol == chr(13) + chr(10) else 'LF'})"


def verify_written(paths, root=None):
    """写后复算（会**抛 SystemExit(2)**，适合直接放在写盘路径末尾）。

    🔴 为什么不信"写的时候没报错"：`qc_evidence_base.py` 曾因闭合 `---` 后漏换行
    **一次性写坏 124 页** —— 文件能打开、正文可读，人工完全看不出，但 frontmatter
    整个解析不出来。唯一能挡住它的是**用同一个解析器读回来**。
    ⚠️ 判据刻意用 `split_frontmatter` 本身，不另写宽松正则：宽松的校验器等于没有校验器。
    """
    root = root or VAULT
    bad = []
    for p in paths:
        if not os.path.isfile(p):
            bad.append((p, "文件不存在（写了但读不回）"))
            continue
        fm, _ = split_frontmatter(read_text(p))
        if not fm.strip():
            bad.append((p, "frontmatter 解析为空（整页元数据会静默丢失）"))
    if bad:
        print("❌ 写后复算不通过：应写 %d ／ 可解析 %d"
              % (len(paths), len(paths) - len(bad)), file=sys.stderr)
        for p, why in bad[:20]:
            try:
                shown = os.path.relpath(p, root)
            except ValueError:
                shown = p
            print("   - %s: %s" % (shown, why), file=sys.stderr)
        raise SystemExit(2)           # 非零退出：让调用链/CI 立刻停下
    print("✅ 写后复算：写 %d 页 / 读回 %d 页，frontmatter 全部可解析"
          % (len(paths), len(paths)))


def backup_files(paths, raise_on_fail=True, root=None):
    """批量备份 -> `{绝对源路径: 备份路径}`（保留原 mtime）。

    `raise_on_fail=True` 时**备份失败即抛错**，不得"打印一句警告就继续写"
    ——那等于没有备份。这正是 CLAUDE.md 写盘铁律 3 的强制形式。
    """
    saved = {}
    for p in paths:
        if not os.path.exists(p):
            continue
        dst = backup_file(p, root=root)
        if not dst:
            if raise_on_fail:
                raise SystemExit(f"备份失败，拒绝写盘（铁律 3：没有回退点就不写）：{p}")
            continue
        try:
            os.utime(dst, (os.path.getatime(p), os.path.getmtime(p)))
        except OSError:
            pass
        saved[os.path.abspath(p)] = dst
    return saved


# ---------------------------------------------------------------- 自检守卫（共享）

def guard_state(root=None, wiki_glob=False, extra_paths=()):
    """对**真实落点**拍 (mtime_ns, size) 快照（含文件集合本身）。

    它要证明的只有一件事：**selftest 一个字节都没落到真实库上**。
    比对的不是内容而是 (mtime, size) + 文件集合，因为这就足以发现任何写入。
    """
    root = root or VAULT
    out = []
    for p in extra_paths:
        p = str(p)
        if os.path.isfile(p):
            st = os.stat(p)
            out.append((p, st.st_mtime_ns, st.st_size))
        elif os.path.isdir(p):
            for dp, _dn, fns in os.walk(p):
                for fn in fns:
                    f = os.path.join(dp, fn)
                    try:
                        st = os.stat(f)
                    except OSError:
                        continue
                    out.append((f, st.st_mtime_ns, st.st_size))
    if wiki_glob:
        for dp, dns, fns in os.walk(os.path.join(root, "wiki")):
            dns[:] = [d for d in dns if d not in (".index", ".claude-rename")]
            for fn in fns:
                if not fn.endswith(".md"):
                    continue
                f = os.path.join(dp, fn)
                try:
                    st = os.stat(f)
                except OSError:
                    continue
                out.append((f, st.st_mtime_ns, st.st_size))
    return sorted(out)


def guard_diff(before, after):
    """两次 `guard_state` 的差异（修改/新增/缺失），供自检守卫断言"0 处变化"。"""
    bd = dict((p, (m, s)) for p, m, s in before)
    ad = dict((p, (m, s)) for p, m, s in after)
    out = ["修改 " + p for p in ad if p in bd and bd[p] != ad[p]]
    out += ["新增 " + p for p in ad if p not in bd]
    out += ["缺失 " + p for p in bd if p not in ad]
    return out


# ---------------------------------------------------------------- CLI 参数解析（共享）

def parse_budget(s):
    """`"5,5,8"` → `{"L1":5,"L2":5,"L3":8}`；空串/None → `None`。

    🔴 **单一实现**：这段解析此前在 `kb.py`、`kb_route.py`、`kb_serve.py` 里
    **各写了一遍**（三份拷贝，其中两份还各带一份 layers 解析）。
    三份同源代码必然漂移——本库已有多次"同一错误的两个独立实现"的教训
    （见 CLAUDE.md §已知陷阱 第 1b 条）。
    放在 `kb_lib` 而不是 `kb.py`，是为了避免 `kb_route`/`kb_serve` 反向 import `kb.py`
    造成循环依赖。
    """
    if not s:
        return None
    parts = [int(x) for x in str(s).split(",") if str(x).strip()]
    return {f"L{i + 1}": v for i, v in enumerate(parts[:3])}


def parse_layers(s, default=(1, 2, 3)):
    """`"1,2"` → `(1,2)`；空串/None → `default`（默认三层全跑）。"""
    if not s:
        return tuple(default)
    return tuple(int(x) for x in str(s).split(",") if str(x).strip())


# ------------------------------------------------------------------ CLI

def main(argv=None):
    """最小 CLI。

    🔴 为什么一个"纯库"也要有 `__main__`：`kb_toolcheck.py` 的判定是
    「源码里出现 `selftest` 字样 → 实跑 `--selftest`」，而本文件里到处出现
    `kb_selftest` 这个词 ⇒ 它会跑 `python kb_lib.py --selftest`，那是个**无输出的空操作**，
    退出码 0 ⇒ 报告写成 **PASS**。也就是说：**它在报告里一直是绿的，但从来没被检查过**
    ——这正是 CLAUDE.md 「『有字符串』≠『功能正常』」那一类失效。
    现在把底座不变量**真的**挂上来（复用 kb_selftest，避免两份实现漂移）。
    """
    import argparse
    ap = argparse.ArgumentParser(
        prog="kb_lib.py",
        description="知识库共享库（被其它工具 import）。直接运行只做底座自检。")
    ap.add_argument("--selftest", action="store_true",
                    help="跑 kb_selftest 的底座不变量（frontmatter 重组/换行归一/出链剔除…）")
    args = ap.parse_args(argv)
    if args.selftest:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import kb_selftest
        return kb_selftest.main()
    ap.print_help()
    return 0


if __name__ == "__main__":
    try:                                                       # noqa: SIM105
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except Exception:                                          # noqa: BLE001
        pass
    sys.exit(main())
